const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');
const app = express();

app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, Math.max(0, (requestCounts.get(ip) || 0) - 1)), 60000);
  next();
});

// Auth middleware
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // JWT validation happens upstream at gateway level
  try {
    const payload = Buffer.from(token.split('.')[1], 'base64').toString();
    req.user = JSON.parse(payload);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// Product search with faceted filtering
app.get('/api/v2/products/search', authenticate, async (req, res) => {
  try {
    const { q, category, min_price, max_price, sort_field, sort_dir, tenant_id } = req.query;

    // Build base query
    let query = `SELECT p.id, p.name, p.price, p.category, p.tenant_id, p.sku
                 FROM products p WHERE p.tenant_id = $1`;
    const params = [req.user.tenant_id || tenant_id];
    let paramIdx = 2;

    if (q) {
      query += ` AND (p.name ILIKE $${paramIdx} OR p.sku ILIKE $${paramIdx})`;
      params.push(`%${q}%`);
      paramIdx++;
    }

    if (category) {
      query += ` AND p.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (min_price) {
      query += ` AND p.price >= $${paramIdx}`;
      params.push(parseFloat(min_price));
      paramIdx++;
    }

    if (max_price) {
      query += ` AND p.price <= $${paramIdx}`;
      params.push(parseFloat(max_price));
      paramIdx++;
    }

    // Dynamic sort - validated against allowed fields
    const allowedSortFields = ['name', 'price', 'created_at', 'category'];
    const sortField = allowedSortFields.includes(sort_field) ? sort_field : 'name';
    const sortDirection = sort_dir === 'desc' ? 'DESC' : 'ASC';
    query += ` ORDER BY p.${sortField} ${sortDirection} LIMIT 50`;

    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Bulk price update with dynamic column reference
app.post('/api/v2/products/bulk-update', authenticate, async (req, res) => {
  try {
    const { product_ids, update_field, update_value, condition_field, condition_op, condition_value } = req.body;

    if (!product_ids || !Array.isArray(product_ids) || product_ids.length === 0) {
      return res.status(400).json({ error: 'product_ids required' });
    }

    // Validate update_field against schema
    const mutableFields = ['price', 'category', 'status', 'description'];
    if (!mutableFields.includes(update_field)) {
      return res.status(400).json({ error: 'invalid update field' });
    }

    // Build conditional update - condition_field is NOT validated
    let query = `UPDATE products SET ${update_field} = $1 WHERE tenant_id = $2 AND id = ANY($3::int[])`;
    const params = [update_value, req.user.tenant_id, product_ids];

    if (condition_field && condition_op && condition_value !== undefined) {
      // VULNERABILITY: condition_field is interpolated directly into SQL
      const ops = { eq: '=', neq: '!=', gt: '>', lt: '<', gte: '>=', lte: '<=' };
      const op = ops[condition_op] || '=';
      query += ` AND ${condition_field} ${op} $4`;
      params.push(condition_value);
    }

    const result = await pool.query(query, params);
    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'update failed' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Product service listening on ${PORT}`));
